                                              'migrations."""\n'
                                              'import json\n'
                                              'import sqlite3\n'
                                              'from contextlib import closing, contextmanager\n'
                                              'from datetime import datetime, timezone\n'
                                              'from decimal import Decimal\n'
                                              'from pathlib import Path\n'
                                              'from uuid import uuid4\n'
                                              '\n'
                                              '\n'
                                              'def utc_now():\n'
                                              '    return '
                                              'datetime.now(timezone.utc).isoformat(timespec="microseconds")\n'
                                              '\n'
                                              '\n'
                                              'def sql_instant(column):\n'
                                              '    # Internal column names only. PostgreSQL +00 offsets need '
                                              ':00 for SQLite.\n'
                                              '    return ("julianday(CASE WHEN substr(" + column + ",-3,1) '
                                              'IN (\'+\',\'-\') "\n'
                                              '            "AND substr(" + column + ",-2) GLOB '
                                              '\'[0-9][0-9]\' THEN " + column + "||\':00\' ELSE " + column + '
                                              '" END)")\n'
                                              '\n'
                                              '\n'
                                              '@contextmanager\n'
                                              'def connect(path):\n'
                                              '    # Do not recreate a database deleted while the service is '
                                              'running.\n'
                                              '    with '
                                              'closing(sqlite3.connect(Path(path).resolve().as_uri() + '
                                              '"?mode=rw", uri=True, timeout=5)) as connection:\n'
                                              '        connection.row_factory = sqlite3.Row\n'
                                              '        connection.execute("PRAGMA foreign_keys=ON")\n'
                                              '        connection.execute("PRAGMA busy_timeout=5000")\n'
                                              '        with connection:\n'
                                              '            yield connection\n'
                                              '\n'
                                              '\n'
                                              'def migrate(path, backup_required=True):\n'
                                              '    root = Path(__file__).resolve().parent\n'
                                              '    with connect(path) as connection:\n'
                                              '        exists = connection.execute("SELECT 1 FROM '
                                              'sqlite_master WHERE '
                                              'name=\'spms_module_migrations\'").fetchone()\n'
                                              '        versions = {row[0] for row in '
                                              'connection.execute("SELECT version FROM '
                                              'spms_module_migrations WHERE module=\'repairs\'")} if exists '
                                              'else set()\n'
                                              '        legacy_versions = {row[0] for row in '
                                              'connection.execute("SELECT version FROM '
                                              'spms_module_migrations WHERE module=\'legacy_import\'")} if '
                                              'exists else set()\n'
                                              '        if legacy_versions - {1}:\n'
                                              "            raise ValueError('Legacy import module is newer "
                                              "than this program; do not downgrade')\n"
                                              '        if versions - {1, 2}:\n'
                                              '            raise ValueError("Database is newer than this '
                                              'program; do not downgrade")\n'
                                              '        if versions == {1, 2} and legacy_versions == {1}:\n'
                                              '            return\n'
                                              '        # SQLite backup includes committed WAL contents. '
                                              'Never overwrite a backup.\n'
                                              '        if backup_required:\n'
                                              '            backup_dir = Path(path).parent / "backups"\n'
                                              '            backup_dir.mkdir(exist_ok=True)\n'
                                              '            filename = "before-repairs-" + '
                                              'datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S") + "-" + '
                                              'uuid4().hex + ".sqlite3"\n'
                                              '            with closing(sqlite3.connect(backup_dir / '
                                              'filename)) as destination:\n'
                                              '                connection.backup(destination)\n'
                                              '        connection.execute("BEGIN IMMEDIATE")\n'
                                              '        connection.execute("""CREATE TABLE IF NOT EXISTS '
                                              'spms_module_migrations (\n'
                                              '            module TEXT NOT NULL, version INTEGER NOT NULL, '
                                              'applied_at TEXT NOT NULL,\n'
                                              '            PRIMARY KEY (module, version))""")\n'
                                              '        versions = {row[0] for row in '
                                              'connection.execute("SELECT version FROM '
                                              'spms_module_migrations WHERE module=\'repairs\'")}\n'
                                              '        legacy_versions = {row[0] for row in '
                                              'connection.execute("SELECT version FROM '
                                              'spms_module_migrations WHERE module=\'legacy_import\'")}\n'
                                              '        if 1 not in versions:\n'
                                              '            run_schema(connection, root / '
                                              "'modules/repairs/schema.sql')\n"
                                              '            catalog = json.loads((root / '
                                              '"modules/repairs/catalog.json").read_text(encoding="utf-8"))\n'
                                              '            connection.executemany("INSERT INTO '
                                              'repair_machine_models VALUES (:machine_code, :model)", '
                                              'catalog["machines"])\n'
                                              '            connection.executemany("INSERT INTO '
                                              'repair_model_boards VALUES (:model, :board_name, '
                                              ':board_part_code)", catalog["boards"])\n'
                                              '            amount_columns = ("board_repair_amount", '
                                              '"external_repair_amount", "contract_repair_amount", '
                                              '"warranty_repair_amount")\n'
                                              '            for price in catalog["prices"]:\n'
                                              '                amounts = [None if price[key] is None else '
                                              'int(Decimal(str(price[key])) * 100) for key in '
                                              'amount_columns]\n'
                                              '                connection.execute("INSERT INTO '
                                              'repair_board_prices VALUES (?,?,?,?,?,?,?)",\n'
                                              '                                   [price["model"], '
                                              'price["board_name"], price["board_part_code"], *amounts])\n'
                                              '            connection.execute("INSERT INTO '
                                              'spms_module_migrations VALUES (\'repairs\', 1, ?)", '
                                              '(utc_now(),))\n'
                                              '        if 2 not in versions:\n'
                                              '            run_schema(connection, root / '
                                              "'modules/repairs/schema_v2.sql')\n"
                                              '            catalog = json.loads((root / '
                                              "'modules/repairs/dbn_catalog.json').read_text(encoding='utf-8'))\n"
                                              "            connection.executemany('INSERT INTO dbn_customers "
                                              "VALUES (?)', [(code,) for code in catalog['customers']])\n"
                                              "            connection.executemany('INSERT INTO "
                                              'dbn_valid_combinations VALUES '
                                              "(:customer_code,:product_code,:station_code)', "
                                              "catalog['combinations'])\n"
                                              "            for row in catalog['sockets']:\n"
                                              "                connection.execute('INSERT INTO "
                                              "dbn_socket_files VALUES (?,?,?,?,?)',\n"
                                              "                                   (row['id'], "
                                              "row['product_code'], row['source_filename'], "
                                              "row['dut_count'], json.dumps(row['dut_pins'])))\n"
                                              '            connection.execute("INSERT INTO '
                                              'spms_module_migrations VALUES (\'repairs\', 2, ?)", '
                                              '(utc_now(),))\n'
                                              '        if not legacy_versions:\n'
                                              '            run_schema(connection, root / '
                                              "'modules/repairs/schema_legacy.sql')\n"
                                              '            connection.execute("INSERT INTO '
                                              'spms_module_migrations VALUES (\'legacy_import\', 1, ?)", '
                                              '(utc_now(),))\n'
                                              '\n'
                                              '\n'
                                              'def run_schema(connection, path):\n'
                                              '    # Reviewed local DDL only; never execute user-supplied '
                                              'SQL.\n'
                                              '    for statement in '
                                              "path.read_text(encoding='utf-8').split(';'):\n"
                                              '        if statement.strip():\n'
                                              '            connection.execute(statement)\n',
